"""Demo: the exact complexity formula d(A) = ceil(log2 |A|)."""
from __future__ import annotations


def clog(base: int, n: int) -> int:
    """Smallest k with n <= base**k (Mathlib's Nat.clog). clog(b,n)=0 if b<=1 or n<=1."""
    if base <= 1 or n <= 1:
        return 0
    k, power = 0, 1
    while power < n:
        power *= base
        k += 1
    return k


def min_distinguishing_depth(card: int) -> int:
    return clog(2, card)


if __name__ == "__main__":
    for card in [1, 2, 3, 4, 5, 8, 9, 16, 100, 1000]:
        d = min_distinguishing_depth(card)
        lo = 2 ** (d - 1) if d > 0 else 0
        print(f"|A|={card:>5}  d={d}  ({lo} < {card} <= {2**d})")

"""Demo: the optimal static questionnaire is the binary code; d-1 predicates fail."""
from __future__ import annotations
from typing import Callable, Dict, List, Sequence, Tuple


def clog(base: int, n: int) -> int:
    if base <= 1 or n <= 1:
        return 0
    k, power = 0, 1
    while power < n:
        power *= base
        k += 1
    return k


def bit_predicate(i: int) -> Callable[[int], bool]:
    return lambda a: bool((a >> i) & 1)


def distinguishes(preds: Sequence[Callable[[int], bool]], elems: Sequence[int]) -> bool:
    seen: Dict[Tuple[bool, ...], int] = {}
    for a in elems:
        prof = tuple(p(a) for p in preds)
        if prof in seen:
            return False
        seen[prof] = a
    return True


if __name__ == "__main__":
    for card in [3, 5, 16, 100]:
        d = clog(2, card)
        elems = list(range(card))
        full: List[Callable[[int], bool]] = [bit_predicate(i) for i in range(d)]
        short: List[Callable[[int], bool]] = [bit_predicate(i) for i in range(d - 1)]
        print(f"|A|={card:>4}  d={d}  d-predicates work={distinguishes(full, elems)}  "
              f"(d-1)-predicates work={distinguishes(short, elems)}")

"""Demo: adaptivity buys no speedup — a decision tree from a static family ties it."""
from __future__ import annotations
from typing import Callable, Dict, List, Sequence, Tuple, Union


def clog(base: int, n: int) -> int:
    if base <= 1 or n <= 1:
        return 0
    k, power = 0, 1
    while power < n:
        power *= base
        k += 1
    return k


class Leaf:
    pass


class Node:
    def __init__(self, query: Callable[[int], bool],
                 if_false: "Union[Node, Leaf]", if_true: "Union[Node, Leaf]") -> None:
        self.query, self.if_false, self.if_true = query, if_false, if_true


def tree_depth(t: "Union[Node, Leaf]") -> int:
    return 0 if isinstance(t, Leaf) else 1 + max(tree_depth(t.if_false), tree_depth(t.if_true))


def transcript(t: "Union[Node, Leaf]", a: int) -> Tuple[bool, ...]:
    out: List[bool] = []
    node = t
    while isinstance(node, Node):
        ans = node.query(a)
        out.append(ans)
        node = node.if_true if ans else node.if_false
    return tuple(out)


def from_preds(preds: Sequence[Callable[[int], bool]]) -> "Union[Node, Leaf]":
    if not preds:
        return Leaf()
    sub = from_preds(preds[1:])
    return Node(preds[0], sub, sub)


def adaptive_ok(t: "Union[Node, Leaf]", elems: Sequence[int]) -> bool:
    seen: Dict[Tuple[bool, ...], int] = {}
    for a in elems:
        tr = transcript(t, a)
        if tr in seen:
            return False
        seen[tr] = a
    return True


if __name__ == "__main__":
    for card in [5, 16, 100]:
        d = clog(2, card)
        preds = [(lambda i: (lambda a: bool((a >> i) & 1)))(i) for i in range(d)]
        tree = from_preds(preds)
        print(f"|A|={card:>4}  clog2={d}  adaptive tree depth={tree_depth(tree)}  "
              f"distinguishes={adaptive_ok(tree, range(card))}")

