function OPTIMAL_STATIC_SYSTEM(card):
    d <- CLOG(2, card)
    preds <- empty list
    for i in 0 .. d-1:
        preds.append( predicate a -> ((a >> i) AND 1) == 1 )
    return preds

function DISTINGUISHES(preds, elements):
    seen <- empty hash set
    for a in elements:
        profile <- tuple( p(a) for p in preds )
        if profile in seen: return False   # twin pair found
        add profile to seen
    return True

